const input = $input.first().json;
const companyInput = $('Company Input').first().json;

// ============================================
// 1. BASIC COMPANY INPUT
// ============================================

let baseUrl = companyInput.website;

if (!baseUrl.startsWith('http://') && !baseUrl.startsWith('https://')) {
  baseUrl = 'https://' + baseUrl;
}

baseUrl = baseUrl.replace(/\/+$/, '');


// ============================================
// 2. URL HELPERS
//
// We deliberately do not use new URL()
// because it wasn't available in your
// n8n Cloud Code environment.
// ============================================

function getHost(url) {
  const match = String(url).match(/^https?:\/\/([^/]+)/i);

  if (!match) return null;

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '');
}


function getOrigin(url) {
  const match = String(url).match(/^(https?:\/\/[^/]+)/i);

  return match ? match[1] : null;
}


function getPath(url) {
  const match = String(url).match(
    /^https?:\/\/[^/?#]+([^?#]*)/i
  );

  return match && match[1]
    ? match[1].toLowerCase()
    : '/';
}


function getPathDepth(path) {
  return path
    .split('/')
    .filter(Boolean)
    .length;
}


const companyHost = getHost(baseUrl);
const companyOrigin = getOrigin(baseUrl);


// ============================================
// 3. NORMALIZE LINKS
// ============================================

function normalizeLink(rawHref) {
  if (!rawHref || typeof rawHref !== 'string') {
    return null;
  }

  let href = rawHref.trim();

  if (!href) return null;

  // Ignore things that aren't normal webpages
  if (
    href.startsWith('#') ||
    href.startsWith('tel:') ||
    href.startsWith('mailto:') ||
    href.startsWith('javascript:') ||
    href.startsWith('data:')
  ) {
    return null;
  }

  let cleanUrl;

  // Absolute URL
  if (
    href.startsWith('http://') ||
    href.startsWith('https://')
  ) {
    cleanUrl = href;
  }

  // Protocol-relative URL
  else if (href.startsWith('//')) {
    cleanUrl = 'https:' + href;
  }

  // Root-relative URL
  else if (href.startsWith('/')) {
    cleanUrl = companyOrigin + href;
  }

  // Other relative path
  else {
    cleanUrl =
      companyOrigin +
      '/' +
      href.replace(/^\.?\//, '');
  }

  // Remove fragment and query parameters
  cleanUrl = cleanUrl.split('#')[0];
  cleanUrl = cleanUrl.split('?')[0];

  // Remove trailing slash unless this is root
  const origin = getOrigin(cleanUrl);

  if (
    origin &&
    cleanUrl !== origin &&
    cleanUrl !== origin + '/'
  ) {
    cleanUrl = cleanUrl.replace(/\/+$/, '');
  }

  return cleanUrl;
}


// ============================================
// 4. CHECK WHETHER PAGE BELONGS TO COMPANY
//
// Allows:
//
// company.com
// www.company.com
// jobs.company.com
// careers.company.com
//
// This is important for companies whose
// careers site lives on a subdomain.
// ============================================

function isCompanySite(url) {
  const host = getHost(url);

  if (!host || !companyHost) return false;

  return (
    host === companyHost ||
    host.endsWith('.' + companyHost) ||
    companyHost.endsWith('.' + host)
  );
}


// ============================================
// 5. GENERIC HARD EXCLUSIONS
//
// Only remove pages that almost never provide
// useful enterprise research.
// ============================================

function shouldExclude(url) {
  const path = getPath(url);

  const utilityPatterns = [
    '/privacy',
    '/legal',
    '/terms',
    '/cookies',
    '/cookie-policy',
    '/accessibility',
    '/sitemap',
    '/login',
    '/signin',
    '/sign-in',
    '/account',
    '/cart',
    '/checkout'
  ];

  if (
    utilityPatterns.some(pattern =>
      path.includes(pattern)
    )
  ) {
    return true;
  }

  // Static files
  if (
    /\.(jpg|jpeg|png|gif|webp|svg|ico|css|js|pdf|zip)$/i
      .test(path)
  ) {
    return true;
  }

  if (
    path.includes('/wp-content/') ||
    path.includes('/assets/')
  ) {
    return true;
  }

  return false;
}


// ============================================
// 6. SCORE A PAGE ACROSS FOUR RESEARCH TYPES
//
// We want evidence diversity:
//
// A. workforce
// B. company
// C. footprint
// D. news / growth
//
// Training is NOT automatically valuable.
// It must look like workforce training.
// ============================================

function scoreUrl(url) {
  const path = getPath(url);
  const host = getHost(url);
  const depth = getPathDepth(path);

  const scores = {
    workforce: 0,
    company: 0,
    footprint: 0,
    news: 0
  };


  // ------------------------------------------
  // A. WORKFORCE / CAREERS
  // ------------------------------------------

  if (
    host.startsWith('jobs.') ||
    host.startsWith('careers.')
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      120
    );
  }

  if (
    path.includes('/careers') ||
    path.includes('/career')
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      115
    );
  }

  if (
    path.includes('/jobs') ||
    path.includes('/job/')
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      110
    );
  }

  if (
    path.includes('apprentice') ||
    path.includes('apprenticeship')
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      105
    );
  }

  if (
    path.includes('employment') ||
    path.includes('recruiting') ||
    path.includes('recruitment') ||
    path.includes('talent')
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      95
    );
  }

  if (
    path.includes('/employees') ||
    path.includes('/employee') ||
    path.includes('/people') ||
    path.includes('/workforce')
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      80
    );
  }


  // ------------------------------------------
  // TRAINING LOGIC
  //
  // This is the important Cintas fix.
  //
  // "training" alone is ambiguous:
  // the company may SELL training.
  //
  // Employee/workforce context makes it
  // a strong research signal.
  // ------------------------------------------

  const hasTrainingSignal =
    path.includes('training') ||
    path.includes('learning') ||
    path.includes('academy') ||
    path.includes('development');

  const hasWorkforceContext =
    path.includes('career') ||
    path.includes('job') ||
    path.includes('employee') ||
    path.includes('people') ||
    path.includes('workforce') ||
    path.includes('talent') ||
    path.includes('recruit') ||
    path.includes('apprentice');

  const hasCommercialContext =
    path.includes('/products') ||
    path.includes('/product/') ||
    path.includes('/services/') ||
    path.includes('/solutions/') ||
    path.includes('/shop') ||
    path.includes('/store') ||
    path.includes('/customers/') ||
    path.includes('/clients/');


  // Clearly workforce-related training
  if (
    hasTrainingSignal &&
    hasWorkforceContext
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      100
    );
  }

  // Generic training page:
  // weak signal only, and only if it does NOT
  // look like a commercial product/service.
  else if (
    hasTrainingSignal &&
    !hasCommercialContext &&
    depth <= 2
  ) {
    scores.workforce = Math.max(
      scores.workforce,
      40
    );
  }


  // ------------------------------------------
  // B. COMPANY / ABOUT
  // ------------------------------------------

  if (
    path === '/about' ||
    path === '/company'
  ) {
    scores.company = Math.max(
      scores.company,
      110
    );
  }

  if (
    path.includes('/about') ||
    path.includes('/company') ||
    path.includes('/who-we-are') ||
    path.includes('/our-company') ||
    path.includes('/our-story')
  ) {
    scores.company = Math.max(
      scores.company,
      100
    );
  }

  if (
    path.includes('/leadership') ||
    path.includes('/executives') ||
    path.includes('/management')
  ) {
    scores.company = Math.max(
      scores.company,
      75
    );
  }

  // Investor pages can provide useful scale
  // information, but are not our first choice.
  if (
    path.includes('/investor') ||
    path.includes('/investors')
  ) {
    scores.company = Math.max(
      scores.company,
      65
    );
  }


  // ------------------------------------------
  // C. OPERATING FOOTPRINT
  // ------------------------------------------

  if (
    path.includes('/locations') ||
    path.includes('/location-finder') ||
    path === '/location'
  ) {
    scores.footprint = Math.max(
      scores.footprint,
      105
    );
  }

  if (
    path.includes('/branches') ||
    path.includes('/branch-locations') ||
    path.includes('/offices')
  ) {
    scores.footprint = Math.max(
      scores.footprint,
      90
    );
  }


  // ------------------------------------------
  // D. NEWS / GROWTH
  // ------------------------------------------

  if (path.includes('/newsroom')) {
    scores.news = Math.max(
      scores.news,
      105
    );
  }

  if (
    path.includes('/press') ||
    path.includes('/news/') ||
    path === '/news' ||
    path.includes('/media')
  ) {
    scores.news = Math.max(
      scores.news,
      90
    );
  }


  // Strategic events are particularly useful
  // for enterprise-sales research.
  const strategicGrowthSignal =
    path.includes('acquisition') ||
    path.includes('acquire') ||
    path.includes('merger') ||
    path.includes('expansion') ||
    path.includes('partnership') ||
    path.includes('partner');


  if (strategicGrowthSignal) {
    scores.news = Math.max(
      scores.news,
      110
    );
  }


  // ------------------------------------------
  // DEPTH PENALTY
  //
  // Prefer broad pages like:
  //
  // /careers
  // /about
  // /locations
  // /newsroom
  //
  // over deeply nested pages unless the
  // deeper page has a very strong signal.
  // ------------------------------------------

  const depthPenalty =
    Math.max(0, depth - 2) * 4;

  for (const category of Object.keys(scores)) {
    if (scores[category] > 0) {
      scores[category] =
        Math.max(
          0,
          scores[category] - depthPenalty
        );
    }
  }


  const bestScore = Math.max(
    scores.workforce,
    scores.company,
    scores.footprint,
    scores.news
  );

  return {
    scores,
    bestScore
  };
}


// ============================================
// 7. BUILD UNIQUE CANDIDATES
// ============================================

const candidates = [];
const seen = new Set();

for (const rawHref of input.links || []) {
  const cleanUrl = normalizeLink(rawHref);

  if (!cleanUrl) continue;

  if (!isCompanySite(cleanUrl)) {
    continue;
  }

  if (shouldExclude(cleanUrl)) {
    continue;
  }

  const dedupeKey =
    cleanUrl
      .toLowerCase()
      .replace(/\/$/, '');

  if (seen.has(dedupeKey)) {
    continue;
  }

  seen.add(dedupeKey);

  const scored = scoreUrl(cleanUrl);

  if (scored.bestScore <= 0) {
    continue;
  }

  candidates.push({
    url: cleanUrl,
    scores: scored.scores,
    bestScore: scored.bestScore
  });
}


// ============================================
// 8. SELECT DIVERSE RESEARCH PAGES
//
// Rather than blindly picking the top four,
// try to select one page from each category.
// ============================================

const categories = [
  'workforce',
  'company',
  'footprint',
  'news'
];

const selected = [];
const selectedSet = new Set();


for (const category of categories) {
  const options = candidates
    .filter(candidate =>
      !selectedSet.has(candidate.url) &&
      candidate.scores[category] > 0
    )
    .sort((a, b) => {

      // First: category score
      const scoreDifference =
        b.scores[category] -
        a.scores[category];

      if (scoreDifference !== 0) {
        return scoreDifference;
      }

      // Tie: prefer shorter/broader path
      return (
        getPath(a.url).length -
        getPath(b.url).length
      );
    });


  if (options.length > 0) {
    const winner = options[0];

    selected.push(winner.url);
    selectedSet.add(winner.url);
  }
}


// ============================================
// 9. FALLBACK
//
// Not every company has all four categories.
//
// If a category is missing, fill remaining
// slots with the strongest unused pages.
// ============================================

if (selected.length < 4) {

  const remaining = candidates
    .filter(candidate =>
      !selectedSet.has(candidate.url)
    )
    .sort((a, b) => {

      const scoreDifference =
        b.bestScore - a.bestScore;

      if (scoreDifference !== 0) {
        return scoreDifference;
      }

      return (
        getPath(a.url).length -
        getPath(b.url).length
      );
    });


  for (const candidate of remaining) {

    if (selected.length >= 4) {
      break;
    }

    selected.push(candidate.url);
    selectedSet.add(candidate.url);
  }
}


// ============================================
// 10. OUTPUT
// ============================================

return [
  {
    json: {
      company_name:
        companyInput.company_name,

      website:
        baseUrl,

      homepage_text:
        input.page_text,

      research_urls:
        selected.slice(0, 4)
    }
  }
];

const input = $input.first().json;
const brief = input.brief;

const REQUIRED = "Customer input required";

// Blank stays null. We never interpret missing data as zero.
function num(value) {
  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return null;
  }

  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? n : null;
}

function round(n, decimals = 2) {
  return Number(n.toFixed(decimals));
}

function show(value) {
  return value === null ? REQUIRED : value;
}


// ---------------------
// INPUTS
// ---------------------

const annualHires = num(input.annual_frontline_hires);
const currentRamp = num(input.current_ramp_weeks);
const managerHoursPerHire = num(input.current_manager_hours_per_hire);
const managerHourlyCost = num(input.manager_loaded_hourly_cost);
const annualQualityCost = num(input.annual_quality_cost);

const targetRamp = num(input.target_ramp_weeks);
const managerReductionPct = num(input.manager_time_reduction_pct);
const qualityReductionPct = num(input.quality_cost_reduction_pct);

const quinnCost = num(input.annual_quinn_cost);


// ---------------------
// VALIDATION
// ---------------------

const warnings = [];

const managerPctValid =
  managerReductionPct === null || managerReductionPct <= 100;

const qualityPctValid =
  qualityReductionPct === null || qualityReductionPct <= 100;

const rampValid =
  currentRamp === null ||
  targetRamp === null ||
  targetRamp <= currentRamp;

if (!managerPctValid) {
  warnings.push(
    "Manager time reduction percentage must be between 0 and 100."
  );
}

if (!qualityPctValid) {
  warnings.push(
    "Quality cost reduction percentage must be between 0 and 100."
  );
}

if (!rampValid) {
  warnings.push(
    "Target ramp time cannot be greater than current ramp time."
  );
}


// ---------------------
// MANAGER / TRAINER VALUE
// ---------------------

let managerHoursSavedPerHire = null;
let annualManagerHoursSaved = null;
let annualManagerTimeValue = null;

if (
  managerHoursPerHire !== null &&
  managerReductionPct !== null &&
  managerPctValid
) {
  managerHoursSavedPerHire = round(
    managerHoursPerHire * (managerReductionPct / 100)
  );
}

if (
  managerHoursSavedPerHire !== null &&
  annualHires !== null
) {
  annualManagerHoursSaved = round(
    managerHoursSavedPerHire * annualHires
  );
}

if (
  annualManagerHoursSaved !== null &&
  managerHourlyCost !== null
) {
  annualManagerTimeValue = round(
    annualManagerHoursSaved * managerHourlyCost
  );
}


// ---------------------
// RAMP VALUE
// Operational only — no fake $ conversion
// ---------------------

let rampWeeksSavedPerHire = null;
let annualWorkforceWeeksGained = null;

if (
  currentRamp !== null &&
  targetRamp !== null &&
  rampValid
) {
  rampWeeksSavedPerHire = round(
    currentRamp - targetRamp
  );
}

if (
  rampWeeksSavedPerHire !== null &&
  annualHires !== null
) {
  annualWorkforceWeeksGained = round(
    rampWeeksSavedPerHire * annualHires
  );
}


// ---------------------
// QUALITY / REWORK VALUE
// ---------------------

let annualQualityCostSavings = null;

if (
  annualQualityCost !== null &&
  qualityReductionPct !== null &&
  qualityPctValid
) {
  annualQualityCostSavings = round(
    annualQualityCost * (qualityReductionPct / 100)
  );
}


// ---------------------
// TOTAL QUANTIFIED BENEFIT
// Only use benefit levers we can actually calculate.
// Missing optional levers are NOT treated as zero.
// ---------------------

const benefitValues = [];
const includedBenefitLevers = [];
const missingBenefitLevers = [];

if (annualManagerTimeValue !== null) {
  benefitValues.push(annualManagerTimeValue);
  includedBenefitLevers.push("Manager/trainer time");
} else {
  missingBenefitLevers.push("Manager/trainer time");
}

if (annualQualityCostSavings !== null) {
  benefitValues.push(annualQualityCostSavings);
  includedBenefitLevers.push("Quality/rework cost");
} else {
  missingBenefitLevers.push("Quality/rework cost");
}

const quantifiedAnnualBenefit =
  benefitValues.length > 0
    ? round(benefitValues.reduce((a, b) => a + b, 0))
    : null;


// ---------------------
// ROI
// ---------------------

let netAnnualBenefit = null;
let roiPercent = null;
let paybackMonths = null;

if (
  quantifiedAnnualBenefit !== null &&
  quinnCost !== null &&
  quinnCost > 0
) {
  netAnnualBenefit = round(
    quantifiedAnnualBenefit - quinnCost
  );

  roiPercent = round(
    (netAnnualBenefit / quinnCost) * 100
  );

  if (quantifiedAnnualBenefit > 0) {
    paybackMonths = round(
      (quinnCost / quantifiedAnnualBenefit) * 12
    );
  }
}


// ---------------------
// MODEL STATUS
// ---------------------

let status = REQUIRED;

if (quantifiedAnnualBenefit !== null && quinnCost === null) {
  status = "Benefits partially quantified; Quinn cost required for ROI";
}

if (quantifiedAnnualBenefit !== null && quinnCost !== null) {
  status = "ROI calculated from supplied inputs";
}

if (warnings.length > 0) {
  status = "Input validation required";
}


// ---------------------
// OUTPUT
// ---------------------

return [
  {
    json: {
      brief,

      roi_model: {
        status,

        methodology:
          "Deterministic model using only customer-supplied baselines and scenario assumptions. Missing values are never invented or treated as zero.",

        inputs: {
          annual_frontline_hires: show(annualHires),
          current_ramp_weeks: show(currentRamp),
          current_manager_hours_per_hire: show(managerHoursPerHire),
          manager_loaded_hourly_cost: show(managerHourlyCost),
          annual_quality_cost: show(annualQualityCost),
          target_ramp_weeks: show(targetRamp),
          manager_time_reduction_pct: show(managerReductionPct),
          quality_cost_reduction_pct: show(qualityReductionPct),
          annual_quinn_cost: show(quinnCost)
        },

        calculations: {
          manager_hours_saved_per_hire:
            show(managerHoursSavedPerHire),

          annual_manager_hours_saved:
            show(annualManagerHoursSaved),

          annual_manager_time_value:
            show(annualManagerTimeValue),

          ramp_weeks_saved_per_hire:
            show(rampWeeksSavedPerHire),

          annual_workforce_weeks_gained:
            show(annualWorkforceWeeksGained),

          annual_quality_cost_savings:
            show(annualQualityCostSavings),

          quantified_annual_benefit:
            show(quantifiedAnnualBenefit),

          net_annual_benefit:
            show(netAnnualBenefit),

          roi_percent:
            show(roiPercent),

          payback_months:
            show(paybackMonths)
        },

        included_benefit_levers: includedBenefitLevers,
        missing_benefit_levers: missingBenefitLevers,

        warnings,

        assumption_note:
          "Target ramp time and percentage-reduction assumptions must be supplied or explicitly agreed with the customer. They are not predictions generated by the LLM."
      }
    }
  }
];

const data = $input.first().json;
const brief = data.brief;
const roi = data.roi_model;

const companyInput = $('Company Input').first().json;

const companyName = companyInput.company_name;
const website = companyInput.website;
const meetingContext = companyInput.meeting_context;

function money(value) {
  if (typeof value !== 'number') return value;
  return '$' + value.toLocaleString('en-US', {
    maximumFractionDigits: 0
  });
}

function number(value) {
  if (typeof value !== 'number') return value;
  return value.toLocaleString('en-US', {
    maximumFractionDigits: 2
  });
}

const lines = [];


// -------------------------
// HEADER
// -------------------------

lines.push(`# Quinn Enterprise Meeting Prep — ${companyName}`);
lines.push('');
lines.push(`**Website:** ${website}`);
lines.push(`**Meeting context:** ${meetingContext}`);
lines.push('');


// -------------------------
// MEETING POV
// -------------------------

lines.push('## Meeting POV');
lines.push('');
lines.push(brief.meeting_pov);
lines.push('');


// -------------------------
// COMPANY SNAPSHOT
// -------------------------

lines.push('## Company Snapshot');
lines.push('');

for (const item of brief.company_snapshot) {
  lines.push(`- ${item}`);
}

lines.push('');


// -------------------------
// FRONTLINE EVIDENCE
// -------------------------

lines.push('## Frontline Operations Evidence');
lines.push('');

for (const item of brief.frontline_facts) {

  // The LLM occasionally includes "Source: URL"
  // inside the fact even though source_url is
  // already returned separately.
  //
  // Remove that duplicate before formatting.
  const cleanFact = item.fact
    .replace(
      /\s*Source(?:s)?:\s*https?:\/\/\S+(?:\s*(?:,|;|and)\s*https?:\/\/\S+)*\s*$/i,
      ''
    )
    .trim();

  lines.push(`- ${cleanFact}`);
  lines.push(`  - Source: ${item.source_url}`);
}

lines.push('');


// -------------------------
// QUINN HYPOTHESES
// -------------------------

lines.push('## Quinn Relevance Hypotheses');
lines.push('');

brief.quinn_hypotheses.forEach((item, index) => {
  lines.push(`### ${index + 1}. ${item.hypothesis}`);
  lines.push('');
  lines.push(`**Evidence:** ${item.fact_basis}`);
  lines.push('');
  lines.push(`**Why it matters:** ${item.why_it_matters_for_quinn}`);
  lines.push('');
});


// -------------------------
// DISCOVERY QUESTIONS
// -------------------------

lines.push('## Discovery Questions');
lines.push('');

brief.discovery_questions.forEach((item, index) => {
  lines.push(`${index + 1}. **${item.question}**`);
  lines.push(`   - Why ask: ${item.reason}`);
});

lines.push('');


// -------------------------
// BUSINESS CASE / ROI
// -------------------------

lines.push('## Business Case');
lines.push('');
lines.push(`**Status:** ${roi.status}`);
lines.push('');

if (roi.status === 'Customer input required') {

  lines.push(
    'Public research is insufficient to calculate a defensible ROI. Collect customer-specific operating data during discovery.'
  );

  lines.push('');
  lines.push('### Inputs to Collect');
  lines.push('');

  for (const item of brief.roi_inputs) {
    lines.push(`- **${item.input}**`);
    lines.push(`  - ${item.why_needed}`);
  }

} else {

  const c = roi.calculations;

  lines.push('### Quantified Results');
  lines.push('');

  lines.push(
    `- Manager hours saved per hire: ${number(c.manager_hours_saved_per_hire)}`
  );

  lines.push(
    `- Annual manager hours saved: ${number(c.annual_manager_hours_saved)}`
  );

  lines.push(
    `- Annual manager-time value: ${money(c.annual_manager_time_value)}`
  );

  lines.push(
    `- Ramp weeks saved per hire: ${number(c.ramp_weeks_saved_per_hire)}`
  );

  lines.push(
    `- Annual workforce-weeks gained: ${number(c.annual_workforce_weeks_gained)}`
  );

  lines.push(
    `- Annual quality-cost savings: ${money(c.annual_quality_cost_savings)}`
  );

  lines.push(
    `- Quantified annual benefit: ${money(c.quantified_annual_benefit)}`
  );

  lines.push(
    `- Net annual benefit: ${money(c.net_annual_benefit)}`
  );

  lines.push(
    `- ROI: ${
      typeof c.roi_percent === 'number'
        ? number(c.roi_percent) + '%'
        : c.roi_percent
    }`
  );

  lines.push(
    `- Payback period: ${
      typeof c.payback_months === 'number'
        ? number(c.payback_months) + ' months'
        : c.payback_months
    }`
  );

  lines.push('');
  lines.push(
    `**Included financial levers:** ${
      roi.included_benefit_levers.join(', ') || 'None'
    }`
  );

  if (roi.missing_benefit_levers.length > 0) {
    lines.push(
      `**Unquantified levers:** ${roi.missing_benefit_levers.join(', ')}`
    );
  }

  lines.push('');
  lines.push(`*${roi.assumption_note}*`);
}


// -------------------------
// UNKNOWNS
// -------------------------

lines.push('');
lines.push('## Important Unknowns');
lines.push('');

for (const item of brief.unknowns) {
  lines.push(`- ${item}`);
}


// -------------------------
// SOURCE CONFLICTS
// -------------------------

if (brief.source_conflicts.length > 0) {
  lines.push('');
  lines.push('## Source Conflicts');
  lines.push('');

  for (const item of brief.source_conflicts) {
    lines.push(`- **${item.issue}**`);
    lines.push(`  - Handling: ${item.handling}`);
  }
}


// -------------------------
// WARNINGS
// -------------------------

if (roi.warnings.length > 0) {
  lines.push('');
  lines.push('## ROI Warnings');
  lines.push('');

  for (const warning of roi.warnings) {
    lines.push(`- ${warning}`);
  }
}


// -------------------------
// OUTPUT
// -------------------------

return [
  {
    json: {
      company_name: companyName,
      website,
      meeting_context: meetingContext,

      final_brief_markdown: lines.join('\n'),

      // Preserve structured output as well
      brief,
      roi_model: roi
    }
  }
];

const input = $input.first().json;

let body = input.data || '';
const company = input.company_name || 'Company';

// ============================================
// 1. PRESENTATION CLEANUP
// ============================================

// Put Website and Meeting context on separate lines.
body = body.replace(
  '\n<strong>Meeting context:</strong>',
  '<br>\n<strong>Meeting context:</strong>'
);


// Make plain-text URLs clickable.
//
// The Markdown output currently leaves source URLs
// as text. Convert them to links while preserving
// punctuation that follows the URL.
body = body.replace(
  /https?:\/\/[^\s<]+/g,
  (match) => {
    let url = match;
    let trailing = '';

    // Don't accidentally include sentence punctuation
    // or semicolons separating multiple sources.
    while (
      url.length > 0 &&
      /[.,;:]$/.test(url)
    ) {
      trailing = url.slice(-1) + trailing;
      url = url.slice(0, -1);
    }

    return `<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>${trailing}`;
  }
);


// ============================================
// 2. DISCOVERY QUESTION WRAPPER
//
// Markdown created a separate <ol> for every
// question. Wrap the whole section so CSS can
// maintain continuous numbering.
// ============================================

body = body.replace(
  /(<h2 id="discoveryquestions">[\s\S]*?)(?=<h2 id="businesscase">)/,
  '<section class="discovery-section">$1</section>'
);


